function courseQuestion109(q){if(q.prompt&&q.answer_key)return q;return {...q,prompt:q.question,accepted_option_ids:[q.answer_id],answer_key:{answer:q.answer,reason:q.reason}}}
function sectionPool109(l){const sec=l.sections.find(x=>session.readingPage>=x.start&&session.readingPage<=x.end);const names=[...new Set(l.course_pages.slice(sec.start,sec.end+1).flatMap(p=>p.card_names||[]))];const matched=l.questions.filter(q=>names.some(n=>q.prompt.includes(n)));if(matched.length)return matched;const bank=FLOW108.bank.filter(q=>q.courseIds.includes(l.id)&&(!names.length||names.includes(q.card_name)));if(bank.length)return bank.map(courseQuestion109);const fallback=l.questions.slice();fallback.sectionFallback=true;return fallback}
const lastBindDeep109=bindReadingPanel;
bindReadingPanel=function(l){lastBindDeep109(l);const panel=$('#course-reading-panel');panel.insertAdjacentHTML('beforeend','<div class="practice-choice-actions"><button class="primary" id="practice-section">练当前小节</button><button class="secondary" id="practice-unfinished">继续未完成题组</button><button class="secondary" id="practice-due">复习待练题</button><button class="secondary" id="read-only">切回阅读</button></div>');const begin=(pool,mode)=>{if(pool.sectionFallback)toast('本小节暂无独立题，提供本课相关复习');if(!pool.length)return toast('当前没有待练题，可练当前小节');session.qs=Learning109.pick(pool,state.attempts||[],8);session.practiceMode=mode;session.practiceOffset=0;session.qi=0;session.chosen=null;session.revealed=false;session.step=2;remember();render()};$('#fresh-practice').textContent='练习本课';$('#fresh-practice').onclick=()=>begin(l.questions,'course');$('#practice-section').onclick=()=>begin(sectionPool109(l),'section');$('#practice-due').onclick=()=>begin(l.questions.filter(q=>Learning109.due(state.attempts||[],q.id)),'due');$('#practice-unfinished').onclick=()=>{if(!session.qs?.length||(!session.chosen&&!session.qi&&session.practiceMode===undefined))return toast('暂无未完成题组');session.step=2;remember();render()};$('#read-only').onclick=()=>{session.step=1;remember();render()}}
const lastLessonDeep109=lessonView;
lessonView=function(){lastLessonDeep109();if(!session||session.id==='review')return;const l=DATA.lessons.find(l=>l.id===session.id);if(session.step===2){$('#app').insertAdjacentHTML('afterbegin','<button class="link" id="practice-switch-read">← 切回阅读，保留题组</button>');$('#practice-switch-read').onclick=()=>{session.step=1;remember();render()}}if(session.step===3){const records=session.qs.map(q=>({q,attempt:(state.attempts||[]).filter(a=>a.qid===q.id&&a.lesson===l.id).slice(-1)[0]}));const review=records.filter(x=>!x.attempt?.correct||x.attempt?.revealed).slice(0,3);$('#app').insertAdjacentHTML('beforeend','<section class="panel group-recap"><h2>本组回顾</h2><p>涉及：'+E([...new Set(session.qs.map(q=>q.knowledge_point||q.category||q.prompt.match(/画面观察|行动建议|复盘|牌位|表达/)?.[0]||'本课应用'))].join('、'))+'</p><p>'+records.filter(x=>x.attempt?.revealed).length+'题看过提示；提示后回答与独立回答分开记录。</p>'+(review.length?'<h3>建议回看</h3>'+review.map(x=>'<p>'+E(x.q.prompt)+'</p>').join(''):'<p>本组暂未发现待练点，可在实际记录中继续检验。</p>')+'</section>');const button=$('#next-practice-group');if(button)button.onclick=()=>{const remaining=l.questions.filter(q=>!session.qs.some(x=>x.id===q.id)&&!(state.attempts||[]).some(a=>a.lesson===l.id&&a.qid===q.id));if(!remaining.length)return toast('本课未做题已完成，可以回看待练题');session.practiceOffset=(session.practiceOffset||0)+session.qs.length;session.qs=Learning109.pick(remaining,state.attempts||[],8);session.qi=0;session.chosen=null;session.revealed=false;session.step=2;remember();render()}}};
comparePractice109=function(l){const origin={...session},c=COMPARE_CASES109.find(c=>c.course===l.id)||COMPARE_CASES109[0];let context=Math.floor(Math.random()*c.backgrounds.length),stage=0,selected=[],answers=[],first=[];const reasons=c.reasons;const stages=['比较适用条件','选择画面依据','指出缺少的事实','选择可验证行动'];function show(){const evidence=stage===1;const opts=stage===0?[['A','解释A更适用'],['B','解释B更适用'],['C','信息不足，先确认事实']]:stage===1?[['A',c.evidence[0]],['B',c.evidence[1]],['C',c.evidenceDistractor]]:stage===2?[['A',c.missing],['B',c.missingAlternatives[0]],['C',c.missingAlternatives[1]]]:[['A',c.actions[context]],['B',c.alternativeActions[0]],['C',c.alternativeActions[1]]];$('#app').innerHTML='<button class="link" id="compare-close">← 返回本课</button><h1>'+E(c.title)+' · 比较训练</h1><section class="panel"><div class="textbook-card-strip">'+c.cards.map((n,i)=>'<figure>'+cardImage(n)+'<figcaption>'+E(c.positions[i]+' · '+n)+'</figcaption></figure>').join('')+'</div><h3>A · 解释一</h3><p>'+E(c.a)+'</p><h3>B · 解释二</h3><p>'+E(c.b)+'</p><p class="tip">'+E(c.source_type)+'</p><p>已知背景：'+E(c.backgrounds[context])+'</p></section><section class="panel"><h2>'+(stage+1)+' / 4 · '+stages[stage]+'</h2>'+(evidence?'<p class="tip">选出两条可核对的画面依据。</p>':'')+Learning109.shuffle(opts).map(([id,t])=>'<button class="option" data-deep-answer="'+id+'" aria-pressed="false">'+E(t)+'</button>').join('')+(evidence?'<button class="secondary" id="confirm-evidence">确认依据</button>':'')+'<div id="deep-feedback" aria-live="polite"></div><button class="primary hidden" id="deep-next">'+(stage===3?'保存本次训练':'继续')+'</button></section>';$('#compare-close').onclick=()=>returnCourseReading109(origin);const confirm=()=>{const expected=stage===0?['A','B','C'][context]:stage===1?'AB':'A';const value=selected.slice().sort().join('');if(first[stage]===undefined)first[stage]=value;answers[stage]={dimension:stages[stage],choice:value,correct:value===expected,reference:expected,optionSnapshot:opts.map(([id,text])=>({id,text})),reason:stage===0?reasons[context]:stage===1?'先选择可见动作或物件，不用画面证明未发生结果。':stage===2?'补充的是现实条件，不能把未知意图或固定词义当事实。':'行动应具体、可实施，并留出检查结果的机会。'};$('#deep-feedback').textContent='参考选择：'+expected.split('').map(id=>opts.find(o=>o[0]===id)?.[1]).join('；')+'。'+answers[stage].reason;$('#deep-next').classList.remove('hidden')};document.querySelectorAll('[data-deep-answer]').forEach(b=>b.onclick=()=>{if(evidence){const id=b.dataset.deepAnswer;selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];b.classList.toggle('selected',selected.includes(id));b.setAttribute('aria-pressed',String(selected.includes(id)))}else{selected=[b.dataset.deepAnswer];confirm()}});if(evidence)$('#confirm-evidence').onclick=confirm;$('#deep-next').onclick=()=>{if(stage<3){stage++;selected=[];show()}else{state.comparisonRuns??=[];state.comparisonRuns.push({id:'cmp-'+Date.now(),courseId:l.id,caseId:c.id,caseTitle:c.title,cards:c.cards,background:c.backgrounds[context],interpretations:[c.a,c.b],answers,firstChoices:first,date:day(),reflections:[]});if(!save()){state.comparisonRuns.pop();return}returnCourseReading109(origin);toast('比较训练已加入能力档案')}}}show()};
const lastHistoryDeep109=history109;
history109=function(){lastHistoryDeep109();$('#app').insertAdjacentHTML('beforeend','<section class="panel"><h2>比较训练档案</h2>'+((state.comparisonRuns||[]).slice().reverse().map(r=>'<button class="journal-entry" data-comparison-record="'+r.id+'"><strong>'+E(r.caseTitle)+'</strong><small>'+E(r.date)+'</small><p>'+E(r.background)+'</p></button>').join('')||'<p class="muted">还没有比较训练，可从相关课程进入。</p>')+'</section>');document.querySelectorAll('[data-comparison-record]').forEach(b=>b.onclick=()=>comparisonRecord109(b.dataset.comparisonRecord))};
function comparisonRecord109(id){const r=state.comparisonRuns.find(r=>r.id===id);$('#app').innerHTML='<button class="link" id="comparison-history-back">← 返回能力档案</button><h1>'+E(r.caseTitle)+'</h1><p>'+E(r.background)+'</p>'+r.interpretations.map((t,i)=>'<p>'+['A','B'][i]+'：'+E(t)+'</p>').join('')+r.answers.map((a,i)=>'<section class="panel"><h3>'+E(a.dimension)+'</h3><p>首次选择：'+E(comparisonChoiceText1018(a,r.firstChoices?.[i]||a.choice))+' · 最后选择：'+E(comparisonChoiceText1018(a,a.choice))+'</p><p>参考答案：'+E(comparisonChoiceText1018(a,a.reference))+'。'+E(a.reason)+'</p></section>').join('')+(r.reflections||[]).map(x=>'<p>'+E(x.date)+' · 后来理解：'+E(x.text)+'</p>').join('')+'<label>后来是否改变理解？<textarea id="comparison-reflection" placeholder="选填，保留原判断"></textarea></label><button class="primary" id="save-comparison-reflection">追加理解</button>';$('#comparison-history-back').onclick=history109;$('#save-comparison-reflection').onclick=()=>{const text=$('#comparison-reflection').value.trim();if(!text)return;r.reflections.push({date:day(),text});save();comparisonRecord109(id)}}
render();

function comparisonChoiceText1018(answer,value){return answer.optionSnapshot?String(value).split('').map(id=>answer.optionSnapshot.find(o=>o.id===id)?.text||id).join('；'):value}
